-- MiniPay initial schema.
-- Amounts are minor units (paise for INR), BIGINT, never floats.
-- IDs are UUIDs generated by the app (see payment.newID), stored as UUID.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS orders (
    id          UUID PRIMARY KEY,
    merchant_id TEXT NOT NULL,
    amount      BIGINT NOT NULL CHECK (amount > 0),
    currency    TEXT NOT NULL CHECK (currency <> ''),
    status      TEXT NOT NULL DEFAULT 'CREATED',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_orders_merchant_created
    ON orders (merchant_id, created_at DESC);

CREATE TABLE IF NOT EXISTS idempotency_keys (
    merchant_id  TEXT NOT NULL,
    key          TEXT NOT NULL,
    request_hash TEXT NOT NULL,
    order_id     UUID REFERENCES orders (id),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (merchant_id, key)
);

CREATE TABLE IF NOT EXISTS payments (
    id              UUID PRIMARY KEY,
    order_id        UUID REFERENCES orders (id),
    merchant_id     TEXT NOT NULL DEFAULT '',
    amount          BIGINT NOT NULL CHECK (amount > 0),
    refunded_amount BIGINT NOT NULL DEFAULT 0 CHECK (refunded_amount >= 0),
    status          TEXT NOT NULL DEFAULT 'CREATED'
        CHECK (status IN ('CREATED', 'AUTHORIZED', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (refunded_amount <= amount)
);
CREATE INDEX IF NOT EXISTS idx_payments_order
    ON payments (order_id);

CREATE TABLE IF NOT EXISTS refunds (
    id         UUID PRIMARY KEY,
    payment_id UUID NOT NULL REFERENCES payments (id),
    amount     BIGINT NOT NULL CHECK (amount > 0),
    status     TEXT NOT NULL DEFAULT 'PENDING',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_refunds_payment
    ON refunds (payment_id);
